cat > test-cli.js << 'EOF'
import { Command } from 'commander';

const program = new Command();

program
  .command('eval')
  .option('--threshold <metric=min>', 'Threshold constraint')
  .action((options) => {
    console.log('Options:', JSON.stringify(options, null, 2));
    console.log('Threshold:', options.threshold);
    console.log('Type:', typeof options.threshold);
  });

program.parseAsync(['node', 'script.js', 'eval', '--threshold', 'exact_match=0.9']);
EOF
node test-cli.js
